CREATE TABLE IF NOT EXISTS users (userId INT AUTO_INCREMENT PRIMARY KEY, fullName VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL UNIQUE, passwordHash VARCHAR(255) NOT NULL, role ENUM('Student','Admin') NOT NULL, createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS courses (courseId INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, name VARCHAR(100) NOT NULL, UNIQUE KEY uq_course_user_name(userId,name), INDEX(userId), FOREIGN KEY(userId) REFERENCES users(userId) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tasks (taskId INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, courseId INT NULL, title VARCHAR(150) NOT NULL, deadline DATETIME NOT NULL, estimatedWorkloadHours DECIMAL(5,2) NOT NULL, preferenceWeight INT NOT NULL DEFAULT 3, status ENUM('Pending','Scheduled','Completed','Unscheduled') NOT NULL DEFAULT 'Pending', INDEX idx_task_owner_deadline(userId,deadline), INDEX(courseId), FOREIGN KEY(userId) REFERENCES users(userId) ON DELETE CASCADE, FOREIGN KEY(courseId) REFERENCES courses(courseId) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS study_sessions (sessionId INT AUTO_INCREMENT PRIMARY KEY, taskId INT NOT NULL, scheduledStart DATETIME NOT NULL, scheduledEnd DATETIME NOT NULL, completed BOOLEAN NOT NULL DEFAULT FALSE, INDEX(taskId), INDEX(scheduledStart), FOREIGN KEY(taskId) REFERENCES tasks(taskId) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS availability (availabilityId INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, dayOfWeek ENUM('Mon','Tue','Wed','Thu','Fri','Sat','Sun') NOT NULL, startTime TIME NOT NULL, endTime TIME NOT NULL, INDEX(userId), FOREIGN KEY(userId) REFERENCES users(userId) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS scheduling_weights (userId INT PRIMARY KEY, urgencyWeight DECIMAL(4,3) NOT NULL DEFAULT 0.550, workloadWeight DECIMAL(4,3) NOT NULL DEFAULT 0.250, preferenceWeight DECIMAL(4,3) NOT NULL DEFAULT 0.200, FOREIGN KEY(userId) REFERENCES users(userId) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS emotion_lexicon (entryId INT AUTO_INCREMENT PRIMARY KEY, word VARCHAR(50) NOT NULL, emotion ENUM('Stressed','Fatigued','Motivated','Frustrated') NOT NULL, weight DECIMAL(3,2) NOT NULL DEFAULT 1.0, updatedBy INT NULL, UNIQUE KEY uq_lexicon(word,emotion), INDEX(updatedBy), FOREIGN KEY(updatedBy) REFERENCES users(userId) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS response_templates (templateId INT AUTO_INCREMENT PRIMARY KEY, intent VARCHAR(50) NOT NULL, emotion ENUM('Stressed','Fatigued','Motivated','Frustrated','Neutral') NOT NULL, responseText TEXT NOT NULL, UNIQUE KEY uq_template(intent,emotion));
CREATE TABLE IF NOT EXISTS chat_messages (messageId INT AUTO_INCREMENT PRIMARY KEY, userId INT NOT NULL, sender ENUM('User','Bot') NOT NULL, content TEXT NOT NULL, detectedEmotion ENUM('Stressed','Fatigued','Motivated','Frustrated','Neutral') NULL, isCrisisFlagged BOOLEAN NOT NULL DEFAULT FALSE, sentAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_chat_user_time(userId,sentAt), FOREIGN KEY(userId) REFERENCES users(userId) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS activity_log (activityId INT AUTO_INCREMENT PRIMARY KEY, userId INT NULL, action VARCHAR(100) NOT NULL, details VARCHAR(500), createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(createdAt), INDEX(userId), FOREIGN KEY(userId) REFERENCES users(userId) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS system_settings (settingKey VARCHAR(100) PRIMARY KEY, settingValue TEXT NOT NULL, updatedBy INT NULL, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(updatedBy), FOREIGN KEY(updatedBy) REFERENCES users(userId) ON DELETE SET NULL);
